import type { Mood } from "./taxonomy";

/**
 * EDITORIAL PHOTOGRAPHY
 * ---------------------
 * Each slot below is a campaign / editorial image. They currently use abstract
 * art-direction backdrops (satin drapes, a watch-dial texture) generated by
 * brand/art/generate.py in the brand palette — never a fake product.
 *
 * To use a real photograph instead: save it to /public/images/editorial/ (JPG or
 * WebP, ~2400px on the long edge), point `src` at it and remove `art: true`.
 * Use only photographs you own or are licensed to use commercially.
 */

export type Tone = "emerald" | "forest" | "charcoal" | "beige" | "ivory";

export interface MediaSlot {
  src: string | null;
  alt: string;
  tone: Tone;
  /** True for the generated art-direction backdrops (abstract, not photographs). */
  art?: boolean;
}

type MoodKey = `mood-${Mood}`;
export type MediaKey =
  | "hero"
  | "heroMobile"
  | "discovery"
  | "collectionDesigner"
  | "collectionArabic"
  | "collectionMen"
  | "collectionWomen"
  | "contact"
  | "watches"
  | "watchesTile"
  | MoodKey;

const art = (file: string, alt: string, tone: Tone): MediaSlot => ({ src: `/images/editorial/${file}`, alt, tone, art: true });

export const media: Record<MediaKey, MediaSlot> = {
  hero: art("hero.jpg", "Emerald satin in soft studio light", "emerald"),
  heroMobile: art("hero-mobile.jpg", "The HC monogram in a gold arch on emerald satin", "emerald"),
  discovery: art("discovery.jpg", "Warm beige satin drape", "beige"),
  collectionDesigner: art("collection-designer.jpg", "Charcoal satin with a soft gold sheen", "charcoal"),
  collectionArabic: art("collection-arabic.jpg", "Amber satin drape", "charcoal"),
  collectionMen: art("collection-men.jpg", "Deep forest-green satin", "forest"),
  collectionWomen: art("collection-women.jpg", "Ivory satin drape", "ivory"),
  contact: { src: null, alt: "The Homies Choice store", tone: "forest" },
  watches: art("watches.jpg", "Sunburst watch-dial texture", "charcoal"),
  watchesTile: art("watches-tile.jpg", "Sunburst watch-dial texture with a gold chapter ring", "charcoal"),
  "mood-fresh-aquatic": art("mood-fresh-aquatic.jpg", "Pale aqua satin", "ivory"),
  "mood-warm-spicy": art("mood-warm-spicy.jpg", "Amber satin", "charcoal"),
  "mood-woody-smoky": art("mood-woody-smoky.jpg", "Charcoal satin", "charcoal"),
  "mood-sweet-gourmand": art("mood-sweet-gourmand.jpg", "Caramel satin", "beige"),
  "mood-elegant-sophisticated": art("mood-elegant-sophisticated.jpg", "Emerald satin", "emerald"),
  "mood-bold-intense": art("mood-bold-intense.jpg", "Deep green satin with bright highlights", "forest"),
};
